/** Read selected for one place expression. */
export type ReadResolution =
    /** Local value binding. */
    | {
          readonly kind: "binding";
          /** The selected binding symbol. */
          readonly symbol: GlobalSymbolId;
          /** The value type produced by the read. */
          readonly ty: GlobalTypeId;
      }
    /** Member read. */
    | {
          readonly kind: "member";
          readonly member: OperationResolution;
      }
    /** Subscript read. */
    | {
          readonly kind: "subscript";
          readonly subscript: OperationResolution;
      }
    /** Dereference read. */
    | {
          readonly kind: "dereference";
          readonly dereference: OperationResolution;
      }
